#!/bin/bash
# build.sh <name>: compile splittick-harness/micro/<name>.cu for PX_CUMETAL into /private/tmp/claude-501/splittick/<name>
W=/Users/glavin/Development/PhysX/.claude/worktrees/splittick; CM=/Users/glavin/Development/cuda-metal/.claude/worktrees/splittick
$CM/out/build/macos-cumetal/release/cumetalc $W/splittick-harness/micro/$1.cu -o /private/tmp/claude-501/splittick/$1 --cuda-clang /opt/homebrew/opt/llvm@21/bin/clang++ --fp64=ieee64 -std=c++17 -I$CM/runtime/api -I$W/out/build/macos-cumetal/release/gpu/physx/include -I$W/physx/include -I$W/physx/source/lowlevel/software/include -I$W/physx/source/lowlevel/api/include -I$W/physx/source/common/include -I$W/physx/source/common/src -I$W/physx/source/gpucommon/include -I$W/physx/source/gpusimulationcontroller/include -I$W/physx/source/gpunarrowphase/include -I$W/physx/source/gpudestruction/src -I$W/physx/source/gpudestruction/include -I$W/blast/include/extensions/stressgpu -I$W/blast/include/extensions/stress -DPX_PHYSX_STATIC_LIB -DNDEBUG -DPX_CUMETAL=1 "${@:2}" 2>&1 | grep -v warning | grep -E "error|failed" | head -20
